insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values
  ('78c26b6b-d54d-582a-a386-212e55e5a1ea', 'Paróquia criada em 2004; o templo novo, iniciado em 2015, recebeu a primeira missa em 2022. Fora do formato: Confissões aos domingos durante as missas, por ordem de chegada Ponto no mapa aproximado: centro da cidade.', '{"https://catedraldepalmas.com.br/horarios-de-missa","https://arquidiocesedepalmas.org.br/paroquias/catedral-divino-espirito-santo/","https://catedraldepalmas.com.br/secretaria"}', 'alta'),
  ('1878619a-43d1-5439-b0e6-26a845e5a679', 'Pró-catedral, criada em 1991; São José é o padroeiro de Palmas. Fora do formato: Sábado: 19h30 na comunidade São Miguel Arcanjo e 18h na comunidade Nossa Senhora do Rosário', '{"https://arquidiocesedepalmas.org.br/paroquias/paroquia-sao-jose-matriz-de-palmas/","https://arquidiocesedepalmas.org.br/paroquias/paroquia-sao-jose-matriz-de-palmas/"}', 'alta'),
  ('212e5ebd-5118-5762-a71b-c2b1817b5ac1', 'Fora do formato: Comunidade Santa Luzia: domingo 8h e 18h, terça 19h30. Comunidade São Paulo Apóstolo: quarta 19h30, domingo 18h Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedepalmas.org.br/paroquias/coracao-de-maria/","https://arquidiocesedepalmas.org.br/paroquias/coracao-de-maria/"}', 'alta'),
  ('1dd060df-7cd5-54f4-809b-b14ea985099a', 'O site da arquidiocese não traz a grade de missas da matriz, só a das comunidades. Fora do formato: O site da arquidiocese lista missas nas comunidades: São João Batista, domingo 10h; Nossa Senhora Aparecida, domingo 8h Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedepalmas.org.br/paroquias/paroquia-cristo-rei/"}', 'media'),
  ('9fb17038-3e66-5f68-bcf2-997bbe7817e9', 'Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedepalmas.org.br/paroquias/paroquia-jesus-bom-pastor/","https://arquidiocesedepalmas.org.br/paroquias/paroquia-jesus-bom-pastor/"}', 'alta'),
  ('8202e4c0-d11a-5b1b-846b-da018d0a62ec', 'O site da arquidiocese não deixou claros os horários de domingo. Fora do formato: Confissões de terça a sexta, das 14h às 17h, com agendamento na secretaria Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedepalmas.org.br/horarios-de-missas/","https://arquidiocesedepalmas.org.br/paroquias/paroquia-jesus-de-nazare/"}', 'media'),
  ('b92ed99f-5da1-55ac-89cd-e04cbe109ce0', 'Paróquia e santuário do Movimento de Schoenstatt. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedepalmas.org.br/paroquias/santuario-mae-rainha/","https://santuariomaerainha.com.br/"}', 'alta'),
  ('1b6da569-082f-5e14-b1ae-d164ad99c2fe', 'Paróquia e santuário. Fora do formato: Confissões de terça a sábado, por ordem de chegada Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedepalmas.org.br/paroquias/santuario-n-sra-de-fatima/","https://arquidiocesedepalmas.org.br/paroquias/santuario-n-sra-de-fatima/","https://www.instagram.com/santuariodefatimapalmas/"}', 'alta'),
  ('3c8047ad-e74a-5d07-83ef-55733fcc17f2', 'Ponto no mapa aproximado: centro da cidade.', '{"https://www.instagram.com/paroquiamontedocarmo/","https://arquidiocesedepalmas.org.br/paroquias/paroquia-n-sra-do-monte-do-carmo/","https://www.facebook.com/ParoquiaNossaSenhoraDoMonteDoCarmo/"}', 'alta'),
  ('22c14f4d-ae2f-50e3-8890-d780c10e3648', 'As missas são nas comunidades Santo Amaro e São Vicente de Paulo; não consta no anuário GCatholic. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedepalmas.org.br/horarios-de-missas/"}', 'media'),
  ('0369ddc2-7b2a-5e03-a614-51201a4a2e49', 'O Facebook da paróquia traz quinta e sexta às 7h; ficou a grade do site da arquidiocese. Fora do formato: Confissões nas tardes de terça, quinta e sexta e na manhã de sábado Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedepalmas.org.br/paroquias/paroquia-santa-filomena/","https://arquidiocesedepalmas.org.br/paroquias/paroquia-santa-filomena/","https://www.facebook.com/psfilomena/"}', 'media'),
  ('8b7ddf6c-5449-5b0a-99d7-ab4be5edb97c', '', '{"https://arquidiocesedepalmas.org.br/paroquias/paroquia-santa-teresinha-do-menino-jesus/","https://arquidiocesedepalmas.org.br/paroquias/paroquia-santa-teresinha-do-menino-jesus/"}', 'alta'),
  ('d786da88-0252-5cd5-9d99-282dc34d4194', 'Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedepalmas.org.br/paroquias/paroquia-santo-antonio-de-padua/","https://arquidiocesedepalmas.org.br/paroquias/paroquia-santo-antonio-de-padua/"}', 'alta'),
  ('6347d447-716f-56bc-8373-bd83b12e35ed', 'Fora do formato: Capela Santíssima Trindade com missas aos domingos Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedepalmas.org.br/horarios-de-missas/","https://arquidiocesedepalmas.org.br/paroquias/paroquia-sao-cristovao/"}', 'alta'),
  ('b15ed9b3-7346-511d-83c9-72db56159f45', 'Igreja dedicada na solenidade de São João Batista. Ponto no mapa aproximado: centro da cidade.', '{"https://psjb.palmas.br/horario-das-missas/","https://arquidiocesedepalmas.org.br/horarios-de-missas/"}', 'alta'),
  ('d89d7598-f3d0-52a6-a96f-c2f5459eae0a', 'Fora do formato: Confissões com agendamento na secretaria Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedepalmas.org.br/paroquias/paroquia-sao-judas/","https://arquidiocesedepalmas.org.br/paroquias/paroquia-sao-judas/"}', 'alta'),
  ('ce302286-6918-5c32-b37f-552725fc69ee', 'Confiada à congregação orionita. Fora do formato: Comunidade Sagrada Família: quinta. Comunidade Imaculado Coração de Maria: quarta Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedepalmas.org.br/paroquias/paroquia-sao-luis-orione/","https://arquidiocesedepalmas.org.br/paroquias/paroquia-sao-luis-orione/"}', 'alta'),
  ('24c11a43-9dee-5f62-85ff-f7603c9b1d34', 'Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedepalmas.org.br/paroquias/paroquia-imaculado-coracao-de-maria/","https://arquidiocesedepalmas.org.br/paroquias/paroquia-imaculado-coracao-de-maria/"}', 'alta'),
  ('7954c46d-a18a-5285-b506-162abdbb6b6a', 'Ponto no mapa aproximado: centro da cidade.', '{"https://www.matrizaparecida.com.br/","https://www.matrizaparecida.com.br/"}', 'alta'),
  ('af759b13-3e41-5654-81fb-e08df45d20b2', 'Fora do formato: Comunidade Santo Expedito: quinta 19h30 e domingo 9h. Comunidades São Felipe Neri, Nossa Senhora das Graças e São João (zona rural)', '{"https://arquidiocesedepalmas.org.br/horarios-de-missas/","https://arquidiocesedepalmas.org.br/festejos-de-nossa-senhora-das-merces-tem-inicio-neste-sabado16/"}', 'alta'),
  ('5dea5070-69a0-59d6-9f04-c2e4f423d852', 'Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedepalmas.org.br/paroquias/paroquia-n-sra-do-perpetuo-socorro/","https://arquidiocesedepalmas.org.br/paroquias/paroquia-n-sra-do-perpetuo-socorro/"}', 'alta'),
  ('f91e9144-eb3d-5d83-98e4-b92e42a3bc55', 'Paróquia do distrito de Taquaruçu; nem o site da arquidiocese nem as redes da paróquia publicam a grade de missas. Ponto no mapa aproximado: centro da cidade.', '{"https://www.facebook.com/taquarucuparoquia/"}', ''),
  ('f9f3350a-e0bd-539c-b4de-c97221c93607', 'Não consta no anuário GCatholic, que ainda não registra as unidades mais novas. Fora do formato: Atendimento do pároco: terça, quinta e sábado das 8h30 às 10h30; quarta e sexta a partir das 16h Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedepalmas.org.br/horarios-de-missas/","https://arquidiocesedepalmas.org.br/paroquias/paroquia-sagrado-coracao-de-jesus/"}', 'alta'),
  ('f288ce96-2503-598f-abe6-1e9eface29a4', 'Fora do formato: Confissões de terça a sexta, das 14h às 16h, com hora marcada Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedepalmas.org.br/paroquias/paroquia-santa-rita-de-cassia/","https://arquidiocesedepalmas.org.br/paroquias/paroquia-santa-rita-de-cassia/"}', 'alta'),
  ('f153bf89-120e-53f3-9c7f-e58bcaf0c3d8', 'Criada em 2002. Fora do formato: Terça na capela Santa Júlia; sexta na capela Nossa Senhora de Guadalupe Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedepalmas.org.br/paroquias/santo-antonio-de-lisboa-aureny-iii/","https://arquidiocesedepalmas.org.br/paroquias/santo-antonio-de-lisboa-aureny-iii/"}', 'alta'),
  ('e68ef8c7-e015-54f4-8578-8588cb8043a7', 'Fora do formato: Capela Nossa Senhora do Desterro: domingo 17h', '{"https://arquidiocesedepalmas.org.br/paroquias/paroquia-santo-expedito/","https://arquidiocesedepalmas.org.br/paroquias/paroquia-santo-expedito/"}', 'alta'),
  ('682d8997-ba82-596f-a3f8-edd7644549db', 'Fora do formato: Missa votiva a São Francisco todo dia 4 do mês, às 19h30 Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedepalmas.org.br/horarios-de-missas/","https://arquidiocesedepalmas.org.br/paroquias/paroquia-sao-francisco-de-assis/"}', 'alta'),
